window.receiveProjectSource({"path": "test/integration/event_synthesis/test_merge_link_service.py", "lines": ["\"\"\"Integration tests for :class:`MergeLinkService.merge_link_one`.", "", "Mirrors ``test_synthesis_service.py``: builds the minimum cross-DB", "scaffolding (Document + DocArticleMap + RawEvent + pre-existing", "SourceEvent) and runs the writer end-to-end. The embedding helpers and the", "MergeLLM client are stubbed so the test does not hit the accelerate ALB or", "the LLM provider.", "", "Covers the confirmed-match update, narrative merge (LLM happy path and", "contract-violation fallback), retrieval substrate recompute, platform", "document evidence write, duplicate-evidence short-circuit, structured", "entity/tag/geo merge rules, idempotent replay, dedup-decision drift on", "replay, lifecycle regression detection, and the null-doc-article-map and", "missing-source-event guards.", "\"\"\"", "", "from __future__ import annotations", "", "import datetime as dt", "from decimal import Decimal", "from typing import Any", "from unittest.mock import AsyncMock", "from uuid import UUID, uuid4", "", "import pytest", "from accelerate_models.common.models.enum.account_type import AccountType", "from accelerate_models.event_synthesis.app.models.event_categories import (", "    EventCategory as AccEventCategory,", ")", "from accelerate_models.event_synthesis.app.models.event_types import EventType as SourceEventType", "from accelerate_models.event_synthesis.app.models.source_event_changes import SourceEventChange", "from accelerate_models.event_synthesis.app.models.source_event_documents import (", "    SourceEventDocument,", ")", "from accelerate_models.event_synthesis.app.models.source_event_entities import SourceEventEntity", "from accelerate_models.event_synthesis.app.models.source_events import SourceEvent", "from sqlalchemy import delete, select, text, update", "from sqlalchemy.dialects.postgresql import insert as pg_insert", "", "import common.models.all  # noqa: F401  cross-package mapper resolution", "from db.session_manager_async import sessionmanager_accelerate, sessionmanager_datalake", "from microservices.entity_classification.models.doc_article_map import DocArticleMap", "from microservices.event_extraction.models.event_categories import EventCategory", "from microservices.event_extraction.models.event_types import EventType as DataLakeEventType", "from microservices.event_extraction.models.raw_events import RawEvent", "from microservices.event_synthesis.config.candidate_retrieval import CandidateRetrievalConfig", "from microservices.event_synthesis.exceptions import EssMergeFlowDataError", "from microservices.event_synthesis.services.merge_link import MergeLinkService", "from microservices.event_synthesis.services.merge_llm import MergeLLMOutcome, MergeLLMOutput", "from microservices.event_synthesis.services.raw_event_repo import RawEventRepository", "from microservices.event_synthesis.services.synthesis import MergeLinkResult", "from test.integration.event_synthesis.helpers import (", "    PlatformEntitySeed,", "    seed_article,", "    seed_doc_documents,", "    seed_ec_layer_one_activity,", "    seed_platform_entity,", ")", "", "pytestmark = pytest.mark.integration", "", "_EMBED_DIMS = 3072", "", "", "# ----------------------------------------------------------------- fixtures", "", "", "async def _category_and_type() -> tuple[UUID, str, UUID, str]:", "    async with sessionmanager_datalake.session() as db:", "        cat_row = (", "            await db.execute(", "                select(EventCategory.id, EventCategory.name).where(EventCategory.name != \"Other\")", "            )", "        ).first()", "        assert cat_row is not None", "        category_id, category_name = cat_row.id, cat_row.name", "", "        type_row = (", "            await db.execute(", "                select(DataLakeEventType.id, DataLakeEventType.name).where(", "                    DataLakeEventType.event_category_id == category_id", "                )", "            )", "        ).first()", "        if type_row is None:", "            type_id = uuid4()", "            type_name = f\"ess-merge-test-type-{type_id}\"", "            db.add(", "                DataLakeEventType(", "                    id=type_id,", "                    event_category_id=category_id,", "                    name=type_name,", "                    created_by=\"event_synthesis_service\",", "                )", "            )", "            await db.commit()", "        else:", "            type_id, type_name = type_row.id, type_row.name", "", "    async with sessionmanager_accelerate.session() as db:", "        await db.execute(", "            pg_insert(AccEventCategory)", "            .values(id=category_id, name=category_name)", "            .on_conflict_do_nothing(index_elements=[AccEventCategory.id])", "        )", "        await db.execute(", "            pg_insert(SourceEventType)", "            .values(id=type_id, event_category_id=category_id, name=type_name)", "            .on_conflict_do_nothing(index_elements=[SourceEventType.id])", "        )", "        await db.commit()", "    return category_id, category_name, type_id, type_name", "", "", "@pytest.fixture", "async def merge_link_fixtures(cleanup_platform_entity_seeds: list[PlatformEntitySeed]):", "    \"\"\"Build cross-DB scaffolding plus a pre-existing source_event to link into.", "", "    Self-seeded: the doc/article/EC-L1-activity chain is created here rather", "    than borrowed from ambient rows, so the suite never skips on a bare DB and", "    the merge path never inherits a borrowed doc's AI-model rollup (the seeded", "    doc has no DocAiModelMap rows, leaving the rollup signal empty).", "    \"\"\"", "    category_id, category_name, type_id, type_name = await _category_and_type()", "", "    # doc.documents id from the high reserved range so it never collides with a", "    # real ingested doc (whose ON CONFLICT DO NOTHING would silently reuse it).", "    doc_id = 999_000_000 + (uuid4().int % 999_999)", "", "    # Seed the accelerate-side scaffolding: a doc.documents FK target for", "    # source_event_documents.document_id, plus a real PlatformEntity (via the", "    # ent.entities INSERT trigger) so display-name resolution finds a live row.", "    # status != READY keeps the doc-ready trigger from firing (it inserts", "    # doc_events + document_queue rows and invokes a Lambda); the merge path", "    # does not gate on doc status.", "    async with sessionmanager_accelerate.session() as ac:", "        await seed_doc_documents(ac, doc_id=doc_id, doc_info={}, status=\"PENDING\")", "        platform_seed = await seed_platform_entity(", "            ac, entity_type=AccountType.CVW, display_name=\"Acme Corp\"", "        )", "        await ac.commit()", "    cleanup_platform_entity_seeds.append(platform_seed)", "", "    dam_id = uuid4()", "    raw_event_id = uuid4()", "    source_event_id = uuid4()", "", "    async with sessionmanager_datalake.session() as db:", "        # DocArticleMap requires real article + EC L1 activity FK targets.", "        article_id = await seed_article(db)", "        ec_activity = await seed_ec_layer_one_activity(db)", "        db.add(", "            DocArticleMap(", "                id=dam_id,", "                layer_one_activity_id=ec_activity.activity_id,", "                article_id=article_id,", "                doc_id=doc_id,", "            )", "        )", "        db.add(", "            RawEvent(", "                id=raw_event_id,", "                doc_article_map_id=dam_id,", "                event_category_id=category_id,", "                event_type_id=type_id,", "                raw_category=category_name,", "                raw_type=type_name,", "                title=\"Acme acquires Beta - update\",", "                summary=\"Updated summary about the acquisition.\",", "                confidence=0.9,", "                event_date=dt.date(2026, 5, 14),", "                article_published_at=dt.datetime(2026, 5, 14, 12, 0, tzinfo=dt.UTC),", "                event_status=\"ongoing\",", "                is_reporting=True,", "                entities_involved=[", "                    {", "                        \"entity_ref\": \"C1\",", "                        \"role\": \"subject\",", "                        \"confidence\": 0.95,", "                        \"entity_id\": str(platform_seed.entity_id),", "                        \"entity_type\": \"CVW\",", "                    }", "                ],", "                topic_tags=[\"m&a\", \"update\"],", "                key_details={\"acquirer\": \"Acme Corp\", \"target\": \"Beta Industries\"},", "                research_hints=[],", "            )", "        )", "        await db.commit()", "", "    # Pre-existing source_event with one already-linked document evidence row", "    # and one entity row, so the merge writer has real state to read.", "    async with sessionmanager_accelerate.session() as db:", "        db.add(", "            SourceEvent(", "                id=source_event_id,", "                event_category_id=category_id,", "                event_type_id=type_id,", "                title=\"Acme acquires Beta\",", "                summary=\"Original summary.\",", "                event_status=\"announced\",", "                event_confidence=Decimal(\"0.8\"),", "                article_count=1,", "                key_details={\"acquirer\": \"Acme Corp\"},", "                research_hints=[],", "                topic_tags=[\"m&a\"],", "                geographic_specificity={\"LOCAL\": 1},", "                scores={},", "                scoring_status=\"scored\",", "                status=\"active\",", "                first_detected_on=dt.datetime(2026, 5, 1, tzinfo=dt.UTC),", "                last_article_on=dt.datetime(2026, 5, 1, tzinfo=dt.UTC),", "                ownership=\"platform\",", "                owner_client_id=None,", "            )", "        )", "        await db.flush()", "        db.add(", "            SourceEventEntity(", "                event_id=source_event_id,", "                entity_id=platform_seed.entity_id,", "                role=\"mentioned\",", "                confidence=Decimal(\"1.0\"),", "            )", "        )", "        await db.commit()", "", "    state: dict[str, Any] = {", "        \"raw_event_id\": raw_event_id,", "        \"dam_id\": dam_id,", "        \"doc_id\": doc_id,", "        \"category_id\": category_id,", "        \"type_id\": type_id,", "        \"platform_entity_id\": platform_seed.entity_id,", "        \"source_event_id\": source_event_id,", "    }", "    yield state", "", "    # Delete source_events first: its ondelete=CASCADE on event_id clears the", "    # source_event_documents that FK into doc.documents, so the doc delete below", "    # is unblocked. PlatformEntity rows are released by the", "    # cleanup_platform_entity_seeds fixture (ent.entities first, then backing row).", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            text(\"DELETE FROM event_synth.source_events WHERE id = :sid\"),", "            {\"sid\": str(source_event_id)},", "        )", "        await ac.execute(", "            text(\"DELETE FROM doc.documents WHERE id = :did\"),", "            {\"did\": doc_id},", "        )", "        await ac.commit()", "    # Datalake teardown in FK order: raw_event -> doc_article_map -> EC L1", "    # activity -> its sent_sqs_messages parent -> article.", "    async with sessionmanager_datalake.session() as dl:", "        await dl.execute(delete(RawEvent).where(RawEvent.id == raw_event_id))", "        await dl.execute(delete(DocArticleMap).where(DocArticleMap.id == dam_id))", "        await dl.execute(", "            text(\"DELETE FROM entity_classification.layer_one_activities WHERE id = :aid\"),", "            {\"aid\": str(ec_activity.activity_id)},", "        )", "        await dl.execute(", "            text(\"DELETE FROM ai_questionnaire.sent_sqs_messages WHERE msg_tracking_id = :mid\"),", "            {\"mid\": str(ec_activity.msg_tracking_id)},", "        )", "        await dl.execute(", "            text(\"DELETE FROM web_extraction.articles WHERE id = :aid\"),", "            {\"aid\": str(article_id)},", "        )", "        await dl.commit()", "", "", "def _stub_embeddings(monkeypatch: pytest.MonkeyPatch) -> None:", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.embed_summary_text\",", "        AsyncMock(return_value=[0.001] * _EMBED_DIMS),", "    )", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.compute_retrieval_embedding\",", "        AsyncMock(return_value=([0.002] * _EMBED_DIMS, \"text-embedding-3-large\")),", "    )", "", "", "def _stub_merge_llm(monkeypatch: pytest.MonkeyPatch, outcome: MergeLLMOutcome) -> AsyncMock:", "    \"\"\"Patch :meth:`MergeLLMClient.merge` to return ``outcome``.\"\"\"", "    mock = AsyncMock(return_value=outcome)", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_llm.MergeLLMClient.merge\", mock", "    )", "    return mock", "", "", "def _success_outcome(**narrative_overrides: Any) -> MergeLLMOutcome:", "    body: dict[str, Any] = {", "        \"title\": \"Merged Acme/Beta\",", "        \"summary\": \"Merged summary.\",", "        \"key_details\": {\"acquirer\": \"Acme Corp\", \"target\": \"Beta Industries\"},", "        \"research_hints\": [],", "        \"event_date\": \"2026-05-14\",", "        \"event_date_precision\": \"exact_date\",", "        \"event_status\": \"ongoing\",", "        \"rationale\": \"merged\",", "    }", "    body.update(narrative_overrides)", "    from common.models.enums import ChatModel", "", "    return MergeLLMOutcome(", "        narrative=MergeLLMOutput(**body),", "        chat_model=ChatModel.GPT_6_LUNA,", "        fallback_used=False,", "        outage=False,", "    )", "", "", "def _outage_outcome() -> MergeLLMOutcome:", "    return MergeLLMOutcome(", "        narrative=None,", "        chat_model=None,", "        fallback_used=True,", "        outage=True,", "    )", "", "", "def _make_service() -> MergeLinkService:", "    from common.models.enums import ChatModel", "    from common.services.api_helper import APIHelper", "    from common.services.llm_chat import LLMChatParams", "    from microservices.event_synthesis.services.merge_llm import MergeLLMClient", "", "    params = LLMChatParams(", "        microservice_id=\"test\",", "        endpoint_path=\"/api/v1/ai/llm-chat\",", "        default_chat_model=ChatModel.GPT_6_LUNA,", "        default_reasoning=\"low\",", "        default_verbosity=\"low\",", "        default_max_tokens=1024,", "        total_timeout_s=30.0,", "        connect_timeout_s=10.0,", "        socket_read_timeout_s=40.0,", "        socket_connect_timeout_s=10.0,", "    )", "    merge_llm = MergeLLMClient(", "        api_helper=APIHelper(),", "        params=params,", "        fallback_chat_model=ChatModel.CLAUDE_HAIKU_4_5,", "        openai_api_key=\"test\",", "        anthropic_api_key=\"test\",", "    )", "    return MergeLinkService(", "        api_helper=APIHelper(),", "        retrieval_config=CandidateRetrievalConfig(),", "        merge_llm=merge_llm,", "        closure_max_hops=10,", "        closure_max_owners=200,", "    )", "", "", "async def _load_raw_event(raw_event_id: UUID) -> RawEvent:", "    async with sessionmanager_datalake.session() as db:", "        return await RawEventRepository().get_required(db, raw_event_id)", "", "", "# ----------------------------------------------------------------- tests", "", "", "async def test_confirmed_merge_updates_source_event_and_writes_article_linked_change(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Merge into existing event updates it; no new source_events row; one article_linked change written.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "    correlation_id = uuid4()", "", "    async with sessionmanager_accelerate.session() as db:", "        pre_count = (await db.execute(select(SourceEvent.id))).scalars().all()", "    pre_se_count = len(pre_count)", "", "    result = await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=correlation_id,", "    )", "    assert isinstance(result, MergeLinkResult)", "    assert result.is_duplicate_evidence is False", "    assert result.source_event_id == merge_link_fixtures[\"source_event_id\"]", "", "    async with sessionmanager_accelerate.session() as db:", "        all_se = (await db.execute(select(SourceEvent.id))).scalars().all()", "        assert len(all_se) == pre_se_count  # no new row", "        change_rows = (", "            (", "                await db.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == result.source_event_id,", "                        SourceEventChange.change_type == \"article_linked\",", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        assert len(change_rows) == 1", "        change = change_rows[0]", "        assert change.triggering_raw_event_id == raw_event.id", "        assert change.correlation_id == correlation_id", "", "        se_row = (", "            await db.execute(select(SourceEvent).where(SourceEvent.id == result.source_event_id))", "        ).scalar_one()", "        assert se_row.last_change_id == change.id", "        assert se_row.article_count == 2", "        assert se_row.scoring_status == \"needs_scoring\"", "", "", "async def test_ac2_narrative_merge_safely_on_llm_success(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"LLM-success merge applies narrative fields atomically \u2014 incl. the apply", "    direction for key_details / research_hints (complements the degenerate-", "    preserve regression test).\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(", "        monkeypatch,", "        _success_outcome(research_hints=[{\"question\": \"q\", \"context\": \"c\", \"impact\": \"high\"}]),", "    )", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    assert se_row.title == \"Merged Acme/Beta\"", "    assert se_row.summary == \"Merged summary.\"", "    assert se_row.event_status == \"ongoing\"", "    assert se_row.event_date == dt.date(2026, 5, 14)", "    # Apply direction: populated key_details + non-empty sanitized research_hints", "    # ARE written (a guard regression that wrongly suppressed these would fail here).", "    assert se_row.key_details == {\"acquirer\": \"Acme Corp\", \"target\": \"Beta Industries\"}", "    assert se_row.research_hints == [{\"question\": \"q\", \"context\": \"c\", \"impact\": \"high\"}]", "", "", "async def test_ac2_degenerate_merge_response_preserves_existing_key_details_and_hints(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Regression: an abstaining merge LLM must NOT null out good data.", "", "    The bug: the LLM \"abstains\" by returning an all-null-valued ``key_details``", "    object / empty ``research_hints`` instead of a top-level null, and the", "    writer (apply guard + ``!= existing`` diff) overwrote the existing populated", "    values with nulls on a MERGED source_event. Fails on the pre-fix code", "    (``is not None`` guard wrote the all-null object); passes with", "    ``has_narrative_signal`` keeping existing. Field-scoped: title/summary in the", "    same response still apply.", "    \"\"\"", "    _stub_embeddings(monkeypatch)", "", "    # Seed a non-empty existing research_hints so keep-existing is observable", "    # (the shared fixture seeds []).", "    existing_hints = [{\"question\": \"Who is the buyer?\", \"context\": \"not named\", \"impact\": \"high\"}]", "    async with sessionmanager_accelerate.session() as db:", "        await db.execute(", "            update(SourceEvent)", "            .where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            .values(research_hints=existing_hints)", "        )", "        await db.commit()", "", "    # Abstain-by-nulling: all-null key_details object + empty research_hints,", "    # with title/summary still populated (those should apply normally).", "    _stub_merge_llm(", "        monkeypatch,", "        _success_outcome(key_details={\"acquirer\": None, \"target\": None}, research_hints=[]),", "    )", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    # Degenerate fields kept existing (NOT overwritten with nulls)...", "    assert se_row.key_details == {\"acquirer\": \"Acme Corp\"}", "    assert se_row.research_hints == existing_hints", "    # ...while genuinely-populated fields from the same response still applied.", "    assert se_row.title == \"Merged Acme/Beta\"", "    assert se_row.summary == \"Merged summary.\"", "", "", "async def test_conservative_link_when_merge_llm_unavailable_preserves_narrative_fields(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Conservative path: narrative unchanged; bookkeeping fields updated.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _outage_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "        change = (", "            (", "                await db.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"],", "                        SourceEventChange.change_type == \"article_linked\",", "                    )", "                )", "            )", "            .scalars()", "            .first()", "        )", "    # Narrative untouched.", "    assert se_row.title == \"Acme acquires Beta\"", "    assert se_row.summary == \"Original summary.\"", "    # Bookkeeping updated.", "    assert se_row.article_count == 2", "    assert se_row.scoring_status == \"needs_scoring\"", "    # Change row records the outage.", "    assert change is not None", "    assert change.change_payload[\"merge_llm_outage\"] is True", "", "", "async def test_merge_recomputes_retrieval_text_and_embedding_after_material_change(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Material change rewrites ``retrieval_text`` + ``retrieval_embedding``.\"\"\"", "    _stub_embeddings(monkeypatch)  # compute_retrieval_embedding returns a vector", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    # The merged title + summary materially change the retrieval substrate.", "    assert se_row.retrieval_text is not None", "    assert \"Merged Acme/Beta\" in se_row.retrieval_text", "    assert \"Merged summary.\" in se_row.retrieval_text", "    # Embedding succeeded -> both columns populated.", "    assert se_row.retrieval_embedding is not None", "    assert se_row.retrieval_embedding_model == \"text-embedding-3-large\"", "", "", "async def test_ac3_retrieval_embedding_failure_preserves_prior_value(", "    merge_link_fixtures,", "    monkeypatch: pytest.MonkeyPatch,", "    record_metrics: list[dict[str, Any]],", ") -> None:", "    \"\"\"when ``compute_retrieval_embedding`` returns (None, None), the", "    prior ``retrieval_embedding`` and model values are preserved -- NOT", "    overwritten with NULL. ``retrieval_text`` is still recomputed.\"\"\"", "    # Seed a pre-existing retrieval embedding on the source_event row.", "    prior_text = \"prior retrieval text\"", "    prior_vec = [0.5] * _EMBED_DIMS", "    prior_model = \"model-v1\"", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            update(SourceEvent)", "            .where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            .values(", "                retrieval_text=prior_text,", "                retrieval_embedding=prior_vec,", "                retrieval_embedding_model=prior_model,", "            )", "        )", "        await ac.commit()", "", "    # Force the embedding call to fail.", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.embed_summary_text\",", "        AsyncMock(return_value=None),", "    )", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.compute_retrieval_embedding\",", "        AsyncMock(return_value=(None, None)),", "    )", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    # retrieval_text IS recomputed (always written on material change).", "    assert se_row.retrieval_text != prior_text", "    assert \"Merged Acme/Beta\" in se_row.retrieval_text", "    # retrieval_embedding + model UNCHANGED (preserved on embedding failure).", "    assert se_row.retrieval_embedding is not None", "    assert se_row.retrieval_embedding_model == prior_model", "", "    failures = [c for c in record_metrics if c[\"metric\"] == \"ess.embedding.failure\"]", "    retrieval_failures = [", "        c for c in failures if \"kind:retrieval\" in c[\"tags\"] and \"path:link\" in c[\"tags\"]", "    ]", "    assert len(retrieval_failures) == 1, failures", "", "", "async def test_ac4_platform_document_evidence_stores_doc_id_and_raw_event_id(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"the inserted ``source_event_documents`` row uses", "    ``raw_event.doc_article_map.doc_id`` as ``document_id`` and keeps the", "    raw-event UUID in ``raw_event_id`` as logical audit context.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    expected_document_id = raw_event.doc_article_map.doc_id", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        evidence = (", "            await db.execute(", "                select(SourceEventDocument).where(", "                    SourceEventDocument.event_id == merge_link_fixtures[\"source_event_id\"],", "                    SourceEventDocument.raw_event_id == raw_event.id,", "                )", "            )", "        ).scalar_one()", "    assert evidence.document_id == expected_document_id", "    assert evidence.raw_event_id == raw_event.id", "", "", "async def test_risk_4_null_doc_article_map_raises_data_error(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"doc_article_map=None surfaces as ``EssMergeFlowDataError``.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    # Force the eager-loaded attr to None for the test (mirrors a missing", "    # relationship resolution in the upstream repo).", "    raw_event.doc_article_map = None  # type: ignore[assignment]", "", "    svc = _make_service()", "    with pytest.raises(EssMergeFlowDataError):", "        await svc.merge_link_one(", "            raw_event,", "            matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "            correlation_id=None,", "        )", "", "", "async def test_risk_8_matched_source_event_missing_raises_data_error(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"matched source_event_id pointing at a non-existent row -> DataError.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    with pytest.raises(EssMergeFlowDataError):", "        await svc.merge_link_one(", "            raw_event,", "            matched_source_event_id=uuid4(),  # not present", "            correlation_id=None,", "        )", "", "", "async def test_duplicate_document_link_skips_count_confidence_scoring_retrieval_change_write(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"(event_id, document_id) already linked => zero writes; counts/confidence/scoring/retrieval/change row untouched.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # Pre-seed the duplicate evidence row.", "    async with sessionmanager_accelerate.session() as db:", "        db.add(", "            SourceEventDocument(", "                event_id=merge_link_fixtures[\"source_event_id\"],", "                document_id=merge_link_fixtures[\"doc_id\"],", "                raw_event_id=uuid4(),  # different raw_event_id -- exercises (event_id, document_id) dedup", "            )", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "    result = await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "    assert result.is_duplicate_evidence is True", "    assert result.source_event_id == merge_link_fixtures[\"source_event_id\"]", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "        change_rows = (", "            (", "                await db.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"]", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "    # Untouched.", "    assert se_row.article_count == 1", "    assert se_row.scoring_status == \"scored\"", "    assert change_rows == []", "", "", "async def test_ac6_entity_role_precedence_and_geo_increment(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"subject > mentioned entity wins; geo dict increments.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # Existing entity row pre-seeded with role='mentioned'; incoming raw_event", "    # has the same entity_id with role='subject' -- subject must win.", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    # Set the raw_event's geographic_specificity so the increment is testable.", "    async with sessionmanager_datalake.session() as db:", "        await db.execute(", "            text(", "                \"UPDATE event_extraction.raw_events SET geographic_specificity='NATIONAL' \"", "                \"WHERE id = :id\"", "            ),", "            {\"id\": merge_link_fixtures[\"raw_event_id\"]},", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        entity_rows = (", "            (", "                await db.execute(", "                    select(SourceEventEntity).where(", "                        SourceEventEntity.event_id == merge_link_fixtures[\"source_event_id\"]", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "", "    assert len(entity_rows) == 1", "    assert entity_rows[0].role == \"subject\"", "    # {LOCAL: 1} + NATIONAL => {LOCAL: 1, NATIONAL: 1}.", "    assert se_row.geographic_specificity == {\"LOCAL\": 1, \"NATIONAL\": 1}", "    # Tags from incoming raw_event are aggregated into source_event.topic_tags", "    # (existing source_event has ['m&a']; incoming has ['m&a', 'update']).", "    # Frequency-wins ordering is fully covered in", "    # test/unit/.../test_merge_helpers.py::test_aggregate_topic_tags.", "    assert sorted(se_row.topic_tags) == [\"m&a\", \"update\"]", "", "", "async def test_ac6_incoming_multi_role_same_entity_picks_highest_precedence(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"when raw_event.entities_involved has TWO rows for the same entity", "    (e.g., mentioned then subject), the reducer must see BOTH and pick the", "    highest-precedence role (subject). A first-seen dedup in normalization", "    would drop ``subject`` and store ``mentioned`` -- the exact bug the", "    third-round impl review (F2) flagged.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # Mutate the seeded raw_event.entities_involved to carry the same entity", "    # twice with different roles. The mentioned row comes first; subject", "    # must still win.", "    platform_entity_id = merge_link_fixtures[\"platform_entity_id\"]", "    multi_role = [", "        {", "            \"entity_ref\": \"C1\",", "            \"role\": \"mentioned\",", "            \"confidence\": 0.9,", "            \"entity_id\": str(platform_entity_id),", "            \"entity_type\": \"CVW\",", "        },", "        {", "            \"entity_ref\": \"C1\",", "            \"role\": \"subject\",", "            \"confidence\": 0.95,", "            \"entity_id\": str(platform_entity_id),", "            \"entity_type\": \"CVW\",", "        },", "    ]", "    async with sessionmanager_datalake.session() as db:", "        await db.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(entities_involved=multi_role)", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        entity_rows = (", "            (", "                await db.execute(", "                    select(SourceEventEntity).where(", "                        SourceEventEntity.event_id == merge_link_fixtures[\"source_event_id\"]", "                    )", "                )", "            )", "            .scalars()", "            .all()", "        )", "    assert len(entity_rows) == 1", "    # Subject (precedence rank 0) wins over mentioned (rank 4).", "    assert entity_rows[0].role == \"subject\"", "", "", "def _spy_logger_warnings(monkeypatch: pytest.MonkeyPatch) -> list[tuple[str, dict[str, Any]]]:", "    \"\"\"Spy on ``merge_link.logger.warning`` calls.", "", "    structlog does NOT route through stdlib ``logging``, so ``caplog`` doesn't", "    capture our log events. Patching ``logger.warning`` captures the structlog", "    call shape (event name + kwargs) directly.", "    \"\"\"", "    from microservices.event_synthesis.services import merge_link as _ml", "", "    captured: list[tuple[str, dict[str, Any]]] = []", "    real = _ml.logger.warning", "", "    def _spy(event_name: str, **kwargs: Any) -> None:", "        captured.append((event_name, kwargs))", "        real(event_name, **kwargs)", "", "    monkeypatch.setattr(_ml.logger, \"warning\", _spy)", "    return captured", "", "", "async def test_risk_2_dedup_decision_drift_on_replay(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"replay where the raw_event is already linked to a DIFFERENT", "    source_event than this attempt's scorer chose. Pre-flight returns the", "    prior commit's event_id (source of truth) and emits a WARNING.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "    warnings_captured = _spy_logger_warnings(monkeypatch)", "", "    # Create a SECOND source_event + a source_event_documents row linking the", "    # incoming raw_event_id to it (NOT to merge_link_fixtures['source_event_id']).", "    drifted_event_id = uuid4()", "    async with sessionmanager_accelerate.session() as db:", "        db.add(", "            SourceEvent(", "                id=drifted_event_id,", "                event_category_id=merge_link_fixtures[\"category_id\"],", "                event_type_id=merge_link_fixtures[\"type_id\"],", "                title=\"Drifted Event\",", "                summary=\"Prior committed result.\",", "                event_status=\"announced\",", "                event_confidence=Decimal(\"0.8\"),", "                article_count=1,", "                key_details={},", "                research_hints=[],", "                topic_tags=[],", "                geographic_specificity={\"LOCAL\": 1},", "                scores={},", "                scoring_status=\"scored\",", "                status=\"active\",", "                first_detected_on=dt.datetime(2026, 5, 1, tzinfo=dt.UTC),", "                last_article_on=dt.datetime(2026, 5, 1, tzinfo=dt.UTC),", "                ownership=\"platform\",", "                owner_client_id=None,", "            )", "        )", "        await db.flush()", "        db.add(", "            SourceEventDocument(", "                event_id=drifted_event_id,", "                # Reuse the fixture's doc_id (guaranteed to exist; FK-safe).", "                # The drift is signaled by event_id != matched_source_event_id;", "                # the replay-anchor pre-flight query keys on raw_event_id, so", "                # the document_id value doesn't matter for exercising replay drift.", "                document_id=merge_link_fixtures[\"doc_id\"],", "                raw_event_id=merge_link_fixtures[\"raw_event_id\"],", "            )", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    result = await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    # Trust the prior commit -- return the drifted event_id (not matched).", "    assert result.is_duplicate_evidence is True", "    assert result.source_event_id == drifted_event_id", "    # WARNING with key dedup_decision_drift_on_replay emitted.", "    drift = [w for w in warnings_captured if w[0] == \"dedup_decision_drift_on_replay\"]", "    assert len(drift) == 1, [w[0] for w in warnings_captured]", "    assert drift[0][1][\"committed_event_id_prior_attempt\"] == str(drifted_event_id)", "    assert drift[0][1][\"matched_source_event_id_this_attempt\"] == str(", "        merge_link_fixtures[\"source_event_id\"]", "    )", "", "    # Clean up the drifted row -- the fixture only knows about the canonical", "    # source_event_id; the drift fixture is local to this test.", "    async with sessionmanager_accelerate.session() as db:", "        await db.execute(", "            text(\"DELETE FROM event_synth.source_events WHERE id = :sid\"),", "            {\"sid\": str(drifted_event_id)},", "        )", "        await db.commit()", "", "", "async def test_risk_7_event_status_lifecycle_regression(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"LLM returns event_status='planned' for an existing 'completed'", "    source_event. The regression IS accepted (LLM's call) but a WARNING with", "    key event_status_regressed is emitted so operators can detect drift.\"\"\"", "    # Pre-set the existing source_event's status to 'completed'.", "    async with sessionmanager_accelerate.session() as db:", "        await db.execute(", "            update(SourceEvent)", "            .where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            .values(event_status=\"completed\")", "        )", "        await db.commit()", "", "    _stub_embeddings(monkeypatch)", "    # LLM returns event_status='planned' -- earlier in lifecycle.", "    _stub_merge_llm(monkeypatch, _success_outcome(event_status=\"planned\"))", "    warnings_captured = _spy_logger_warnings(monkeypatch)", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    # LLM's call accepted: status regressed.", "    assert se_row.event_status == \"planned\"", "    # WARNING emitted with the lifecycle keys.", "    regress = [w for w in warnings_captured if w[0] == \"event_status_regressed\"]", "    assert len(regress) == 1, [w[0] for w in warnings_captured]", "    assert regress[0][1][\"existing\"] == \"completed\"", "    assert regress[0][1][\"new\"] == \"planned\"", "", "", "async def test_idempotent_replay_returns_duplicate_evidence(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Calling merge_link_one twice => second call is duplicate-evidence no-op.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "", "    first = await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "    second = await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    assert first.is_duplicate_evidence is False", "    assert second.is_duplicate_evidence is True", "    assert first.source_event_id == second.source_event_id", "", "    # article_count incremented exactly once.", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    assert se_row.article_count == 2", "", "", "async def test_merge_preserves_existing_taxonomy_when_incoming_differs(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Source-event taxonomy is immutable on merge.", "", "    Incoming raw_event points at a DIFFERENT category/type pair; after merge", "    the source_event still carries the fixture's original taxonomy and the", "    change row's ``fields_changed`` does not list either taxonomy column.", "    \"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # Seed a second taxonomy pair in both DBs so we can point the raw_event", "    # at something that genuinely differs from the existing source_event.", "    other_category_id = uuid4()", "    other_type_id = uuid4()", "    other_category_name = f\"ess-other-cat-{other_category_id}\"", "    other_type_name = f\"ess-other-type-{other_type_id}\"", "    async with sessionmanager_datalake.session() as dl:", "        dl.add(EventCategory(id=other_category_id, name=other_category_name))", "        await dl.flush()", "        dl.add(", "            DataLakeEventType(", "                id=other_type_id,", "                event_category_id=other_category_id,", "                name=other_type_name,", "                created_by=\"event_synthesis_service\",", "            )", "        )", "        await dl.commit()", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            pg_insert(AccEventCategory)", "            .values(id=other_category_id, name=other_category_name)", "            .on_conflict_do_nothing(index_elements=[AccEventCategory.id])", "        )", "        await ac.execute(", "            pg_insert(SourceEventType)", "            .values(", "                id=other_type_id,", "                event_category_id=other_category_id,", "                name=other_type_name,", "            )", "            .on_conflict_do_nothing(index_elements=[SourceEventType.id])", "        )", "        await ac.commit()", "    async with sessionmanager_datalake.session() as dl:", "        await dl.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(event_category_id=other_category_id, event_type_id=other_type_id)", "        )", "        await dl.commit()", "", "    try:", "        raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "        svc = _make_service()", "        await svc.merge_link_one(", "            raw_event,", "            matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "            correlation_id=None,", "        )", "", "        async with sessionmanager_accelerate.session() as db:", "            se_row = (", "                await db.execute(", "                    select(SourceEvent).where(", "                        SourceEvent.id == merge_link_fixtures[\"source_event_id\"]", "                    )", "                )", "            ).scalar_one()", "            change = (", "                await db.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"],", "                        SourceEventChange.change_type == \"article_linked\",", "                    )", "                )", "            ).scalar_one()", "        assert se_row.event_category_id == merge_link_fixtures[\"category_id\"]", "        assert se_row.event_type_id == merge_link_fixtures[\"type_id\"]", "        assert \"event_category_id\" not in change.change_payload[\"fields_changed\"]", "        assert \"event_type_id\" not in change.change_payload[\"fields_changed\"]", "    finally:", "        # Re-point the raw_event back at the fixture's taxonomy so the temp", "        # event_type/category can be deleted without an FK violation. The", "        # fixture's own teardown then handles the raw_event delete.", "        async with sessionmanager_datalake.session() as dl:", "            await dl.execute(", "                update(RawEvent)", "                .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "                .values(", "                    event_category_id=merge_link_fixtures[\"category_id\"],", "                    event_type_id=merge_link_fixtures[\"type_id\"],", "                )", "            )", "            await dl.commit()", "        async with sessionmanager_accelerate.session() as ac:", "            await ac.execute(", "                text(\"DELETE FROM event_synth.event_types WHERE id = :tid\"),", "                {\"tid\": str(other_type_id)},", "            )", "            await ac.execute(", "                text(\"DELETE FROM event_synth.event_categories WHERE id = :cid\"),", "                {\"cid\": str(other_category_id)},", "            )", "            await ac.commit()", "        async with sessionmanager_datalake.session() as dl:", "            await dl.execute(delete(DataLakeEventType).where(DataLakeEventType.id == other_type_id))", "            await dl.execute(delete(EventCategory).where(EventCategory.id == other_category_id))", "            await dl.commit()", "", "", "async def test_merge_writes_event_confidence_from_llm_output(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"LLM-success path with a non-null event_confidence writes the new value.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome(event_confidence=0.95))", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "        change = (", "            await db.execute(", "                select(SourceEventChange).where(", "                    SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"],", "                    SourceEventChange.change_type == \"article_linked\",", "                )", "            )", "        ).scalar_one()", "    assert se_row.event_confidence == Decimal(\"0.9500\")", "    assert \"event_confidence\" in change.change_payload[\"fields_changed\"]", "", "", "async def test_merge_keeps_existing_event_confidence_when_llm_abstains(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"LLM-success path with event_confidence=None preserves the existing value.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())  # default: event_confidence absent -> None", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    svc = _make_service()", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "        change = (", "            await db.execute(", "                select(SourceEventChange).where(", "                    SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"],", "                    SourceEventChange.change_type == \"article_linked\",", "                )", "            )", "        ).scalar_one()", "    assert se_row.event_confidence == Decimal(\"0.8000\")  # the fixture's value", "    assert \"event_confidence\" not in change.change_payload[\"fields_changed\"]", "", "", "async def test_merge_takes_max_event_confidence_on_outage_when_incoming_stronger(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Outage path raises confidence to max(existing, clamped_incoming).\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _outage_outcome())", "", "    # Push raw_event confidence above the fixture's existing 0.8.", "    async with sessionmanager_datalake.session() as dl:", "        await dl.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(confidence=0.95)", "        )", "        await dl.commit()", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "", "    svc = _make_service()", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "    assert se_row.event_confidence == Decimal(\"0.9500\")", "", "", "async def test_merge_never_lowers_event_confidence_on_outage(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Outage path never decreases confidence when incoming is weaker.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _outage_outcome())", "", "    # Lower raw_event confidence below the fixture's 0.8.", "    async with sessionmanager_datalake.session() as dl:", "        await dl.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(confidence=0.5)", "        )", "        await dl.commit()", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "", "    svc = _make_service()", "    await svc.merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    async with sessionmanager_accelerate.session() as db:", "        se_row = (", "            await db.execute(", "                select(SourceEvent).where(SourceEvent.id == merge_link_fixtures[\"source_event_id\"])", "            )", "        ).scalar_one()", "        change = (", "            await db.execute(", "                select(SourceEventChange).where(", "                    SourceEventChange.event_id == merge_link_fixtures[\"source_event_id\"],", "                    SourceEventChange.change_type == \"article_linked\",", "                )", "            )", "        ).scalar_one()", "    assert se_row.event_confidence == Decimal(\"0.8000\")", "    assert \"event_confidence\" not in change.change_payload[\"fields_changed\"]", "", "", "async def test_protocol_conformance() -> None:", "    \"\"\"``MergeLinkService`` matches ``MergeLinkServiceProtocol`` shape.\"\"\"", "    import inspect", "", "    from microservices.event_synthesis.services.synthesis import MergeLinkServiceProtocol", "", "    svc = _make_service()", "    assert callable(getattr(svc, \"merge_link_one\", None))", "    proto_sig = inspect.signature(MergeLinkServiceProtocol.merge_link_one)", "    impl_sig = inspect.signature(svc.merge_link_one)", "    proto_params = [p for p in proto_sig.parameters if p != \"self\"]", "    impl_params = list(impl_sig.parameters)", "    assert proto_params == impl_params", "", "", "async def test_ac7_no_merged_into_id_column_on_source_events() -> None:", "    \"\"\"source-event-to-source-event merge is OUT of MVP scope.\"\"\"", "    cols = {c.name for c in SourceEvent.__table__.columns}", "    assert \"merged_into_id\" not in cols", "", "", "# --------------------------------------- entity materiality reasons", "", "", "async def _load_article_linked_change(source_event_id: UUID) -> SourceEventChange:", "    \"\"\"Return the single ``article_linked`` change row for ``source_event_id``.\"\"\"", "    async with sessionmanager_accelerate.session() as db:", "        change = (", "            (", "                await db.execute(", "                    select(SourceEventChange).where(", "                        SourceEventChange.event_id == source_event_id,", "                        SourceEventChange.change_type == \"article_linked\",", "                    )", "                )", "            )", "            .scalars()", "            .first()", "        )", "    assert change is not None", "    return change", "", "", "async def _seed_existing_entities(", "    source_event_id: UUID,", "    cleanup_seeds: list[PlatformEntitySeed],", "    *,", "    count: int,", "    role: str,", ") -> list[UUID]:", "    \"\"\"Seed ``count`` live platform entities and attach them to the source", "    event with ``role``.", "", "    Pushes the event past :data:`TOP_ENTITY_ROLES_FOR_RETRIEVAL` so additions", "    and role changes that never crack the rendered top-N are exercised", "    end-to-end. Returns the new entity ids.", "    \"\"\"", "    entity_ids: list[UUID] = []", "    async with sessionmanager_accelerate.session() as ac:", "        for i in range(count):", "            seed = await seed_platform_entity(", "                ac, entity_type=AccountType.CVW, display_name=f\"Extra Corp {i}\"", "            )", "            cleanup_seeds.append(seed)", "            entity_ids.append(seed.entity_id)", "        await ac.commit()", "    async with sessionmanager_accelerate.session() as ac:", "        for eid in entity_ids:", "            await ac.execute(", "                pg_insert(SourceEventEntity)", "                .values(", "                    event_id=source_event_id,", "                    entity_id=eid,", "                    role=role,", "                    confidence=Decimal(\"1.0\"),", "                )", "                .on_conflict_do_nothing(index_elements=[\"event_id\", \"entity_id\"])", "            )", "        await ac.commit()", "    return entity_ids", "", "", "async def test_new_entity_emits_entity_added_with_role(", "    merge_link_fixtures,", "    cleanup_platform_entity_seeds: list[PlatformEntitySeed],", "    monkeypatch: pytest.MonkeyPatch,", ") -> None:", "    \"\"\"A merge attaching a previously-absent entity emits ``entity_added``", "    recording the entity's role, regardless of tier.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # New live entity becomes the only incoming entity; the existing entity", "    # (role=mentioned) is untouched, so the new one is a clean addition.", "    async with sessionmanager_accelerate.session() as ac:", "        new_seed = await seed_platform_entity(", "            ac, entity_type=AccountType.CVW, display_name=\"Beta Industries\"", "        )", "        await ac.commit()", "    cleanup_platform_entity_seeds.append(new_seed)", "", "    incoming = [", "        {", "            \"entity_ref\": \"C2\",", "            \"role\": \"subject\",", "            \"confidence\": 0.95,", "            \"entity_id\": str(new_seed.entity_id),", "            \"entity_type\": \"CVW\",", "        }", "    ]", "    async with sessionmanager_datalake.session() as db:", "        await db.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(entities_involved=incoming)", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    await _make_service().merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    change = await _load_article_linked_change(merge_link_fixtures[\"source_event_id\"])", "    added = [r for r in change.materiality_reasons if r[\"code\"] == \"entity_added\"]", "    assert len(added) == 1", "    assert added[0][\"evidence\"] == \"subject\"", "", "", "async def test_role_change_emits_entity_role_changed(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"A role change on an existing entity emits ``entity_role_changed`` from", "    the full role-map diff (base fixture: mentioned -> subject).\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    await _make_service().merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    change = await _load_article_linked_change(merge_link_fixtures[\"source_event_id\"])", "    codes = [r[\"code\"] for r in change.materiality_reasons]", "    assert \"entity_role_changed\" in codes", "    # Same entity, role changed -> not an addition.", "    assert \"entity_added\" not in codes", "    # Per-entity emission records the old->new transition (mentioned -> subject).", "    role_changed = [r for r in change.materiality_reasons if r[\"code\"] == \"entity_role_changed\"]", "    assert len(role_changed) == 1", "    assert role_changed[0][\"evidence\"] == \"mentioned -> subject\"", "", "", "async def test_entity_added_detected_beyond_top_n(", "    merge_link_fixtures,", "    cleanup_platform_entity_seeds: list[PlatformEntitySeed],", "    monkeypatch: pytest.MonkeyPatch,", ") -> None:", "    \"\"\"A new entity is recorded as ``entity_added`` even when the event already", "    has >5 entities and the addition never cracks the rendered top-5. Entity", "    materiality is computed from the full set, not the top-N retrieval cap.\"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    # 5 extra subjects (+ the seeded mentioned one) put the event at 6 entities;", "    # the rendered top-5 is full of subjects.", "    await _seed_existing_entities(", "        merge_link_fixtures[\"source_event_id\"],", "        cleanup_platform_entity_seeds,", "        count=5,", "        role=\"subject\",", "    )", "    # Incoming: a brand-new low-precedence entity that never enters the top-5.", "    async with sessionmanager_accelerate.session() as ac:", "        new_seed = await seed_platform_entity(", "            ac, entity_type=AccountType.CVW, display_name=\"Late Corp\"", "        )", "        await ac.commit()", "    cleanup_platform_entity_seeds.append(new_seed)", "    incoming = [", "        {", "            \"entity_ref\": \"CN\",", "            \"role\": \"mentioned\",", "            \"confidence\": 0.8,", "            \"entity_id\": str(new_seed.entity_id),", "            \"entity_type\": \"CVW\",", "        }", "    ]", "    async with sessionmanager_datalake.session() as db:", "        await db.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(entities_involved=incoming)", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    await _make_service().merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    change = await _load_article_linked_change(merge_link_fixtures[\"source_event_id\"])", "    added = [r for r in change.materiality_reasons if r[\"code\"] == \"entity_added\"]", "    assert len(added) == 1", "    assert added[0][\"evidence\"] == \"mentioned\"", "", "", "async def test_non_top_n_role_change_emits_reason_without_recompute(", "    merge_link_fixtures,", "    cleanup_platform_entity_seeds: list[PlatformEntitySeed],", "    monkeypatch: pytest.MonkeyPatch,", ") -> None:", "    \"\"\"A role change on a NON-top-5 entity emits ``entity_role_changed`` (full", "    diff) but does NOT trigger retrieval recompute -- the top-N gate stays", "    separate from the materiality signal. Narrative + tags are frozen so the", "    role change is the only candidate recompute trigger; the embedding call", "    must not fire.\"\"\"", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.embed_summary_text\",", "        AsyncMock(return_value=[0.001] * _EMBED_DIMS),", "    )", "    embed_mock = AsyncMock(return_value=([0.002] * _EMBED_DIMS, \"text-embedding-3-large\"))", "    monkeypatch.setattr(", "        \"microservices.event_synthesis.services.merge_link.compute_retrieval_embedding\",", "        embed_mock,", "    )", "    # The fixture's seeded doc has no DocAiModelMap rows, so the AI-model rollup", "    # signal is already empty -- the role change is the only recompute candidate.", "    # Freeze every narrative recompute trigger to the existing source_event.", "    _stub_merge_llm(", "        monkeypatch,", "        _success_outcome(", "            title=\"Acme acquires Beta\",", "            summary=\"Original summary.\",", "            key_details={\"acquirer\": \"Acme Corp\"},", "            event_status=\"announced\",", "        ),", "    )", "", "    # 5 extra subjects fill the rendered top-5; the original (mentioned) entity", "    # sits at rank 6. Changing its role to 'object' (rank 2, still behind the", "    # subjects) leaves the rendered top-5 unchanged -> top-N gate stays False.", "    await _seed_existing_entities(", "        merge_link_fixtures[\"source_event_id\"],", "        cleanup_platform_entity_seeds,", "        count=5,", "        role=\"subject\",", "    )", "    incoming = [", "        {", "            \"entity_ref\": \"C1\",", "            \"role\": \"object\",", "            \"confidence\": 0.9,", "            \"entity_id\": str(merge_link_fixtures[\"platform_entity_id\"]),", "            \"entity_type\": \"CVW\",", "        }", "    ]", "    # Freeze topic tags too (no pre-linked docs -> aggregation == incoming tags).", "    async with sessionmanager_datalake.session() as db:", "        await db.execute(", "            update(RawEvent)", "            .where(RawEvent.id == merge_link_fixtures[\"raw_event_id\"])", "            .values(entities_involved=incoming, topic_tags=[\"m&a\"])", "        )", "        await db.commit()", "", "    raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "    await _make_service().merge_link_one(", "        raw_event,", "        matched_source_event_id=merge_link_fixtures[\"source_event_id\"],", "        correlation_id=None,", "    )", "", "    change = await _load_article_linked_change(merge_link_fixtures[\"source_event_id\"])", "    codes = [r[\"code\"] for r in change.materiality_reasons]", "    assert \"entity_role_changed\" in codes", "    role_changed = [r for r in change.materiality_reasons if r[\"code\"] == \"entity_role_changed\"]", "    assert role_changed[0][\"evidence\"] == \"mentioned -> object\"", "    # Two-boolean split: a non-top-5 role change must NOT recompute retrieval.", "    embed_mock.assert_not_called()", "", "", "async def test_merge_increments_count_and_preserves_legacy_score_on_rollup(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"Merging into an existing rollup row moves the count but never the score columns.", "", "    Rows predating the nullable change hold ``weighted_match_score = 1.0000``; rows", "    written after it hold NULL. Those two values are the only marker separating the", "    eras, so the upsert must move ``matched_document_count`` and ``last_matched_on``", "    without touching either score column.", "", "    The seeded scores are deliberately sentinels rather than the realistic ``1.0000``", "    and NULL: re-adding a column to the conflict-update set would write ``1.0`` or", "    ``None``, which is indistinguishable from the realistic values and would leave the", "    regression undetected. Any write to either column changes these sentinels.", "    \"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    from accelerate_models.ai.app.models.ai_models import AiModel", "    from accelerate_models.ai.app.models.doc_ai_model_map import DocAiModelMap", "    from accelerate_models.event_synthesis.app.models.source_event_ai_models import (", "        SourceEventAiModel,", "    )", "", "    ai_model_id = uuid4()", "    source_event_id = merge_link_fixtures[\"source_event_id\"]", "", "    async with sessionmanager_accelerate.session() as db:", "        db.add(AiModel(id=ai_model_id, name=f\"merge-rollup-{ai_model_id}\", description=\"test\"))", "        await db.flush()", "        # The incoming document matches, so the merge path has a rollup to upsert.", "        db.add(", "            DocAiModelMap(", "                document_id=merge_link_fixtures[\"doc_id\"],", "                ai_model_id=ai_model_id,", "                is_match=True,", "                meta={\"data_model_response_id\": str(uuid4())},", "            )", "        )", "        # Sentinels, not the realistic 1.0000/NULL \u2014 see the docstring.", "        db.add(", "            SourceEventAiModel(", "                source_event_id=source_event_id,", "                ai_model_id=ai_model_id,", "                matched_document_count=1,", "                weighted_match_score=Decimal(\"0.5\"),", "                max_confidence=Decimal(\"0.25\"),", "            )", "        )", "        await db.commit()", "", "    try:", "        raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "        svc = _make_service()", "", "        result = await svc.merge_link_one(", "            raw_event,", "            matched_source_event_id=source_event_id,", "            correlation_id=None,", "        )", "        assert result.is_duplicate_evidence is False", "", "        async with sessionmanager_accelerate.session() as db:", "            rollup = (", "                await db.execute(", "                    select(SourceEventAiModel).where(", "                        SourceEventAiModel.source_event_id == source_event_id,", "                        SourceEventAiModel.ai_model_id == ai_model_id,", "                    )", "                )", "            ).scalar_one()", "", "        assert rollup.matched_document_count == 2", "        assert rollup.weighted_match_score == Decimal(\"0.5000\")", "        assert rollup.max_confidence == Decimal(\"0.2500\")", "        assert rollup.last_matched_on is not None", "    finally:", "        # Runs on assertion failure too: the ai.* rows outlive the fixture teardown,", "        # and a leaked ai_models row blocks the next run on its unique name.", "        async with sessionmanager_accelerate.session() as db:", "            await db.execute(", "                text(", "                    \"DELETE FROM event_synth.source_event_ai_models \"", "                    \"WHERE source_event_id = :se_id AND ai_model_id = :ai_id\"", "                ),", "                {\"se_id\": str(source_event_id), \"ai_id\": str(ai_model_id)},", "            )", "            await db.execute(", "                text(", "                    \"DELETE FROM ai.doc_ai_model_map \"", "                    \"WHERE document_id = :doc_id AND ai_model_id = :ai_id\"", "                ),", "                {\"doc_id\": merge_link_fixtures[\"doc_id\"], \"ai_id\": str(ai_model_id)},", "            )", "            await db.execute(", "                text(\"DELETE FROM ai.ai_models WHERE id = :id\"), {\"id\": str(ai_model_id)}", "            )", "            await db.commit()", "", "", "async def test_merge_inserts_new_rollup_row_with_both_scores_null(", "    merge_link_fixtures, monkeypatch: pytest.MonkeyPatch", ") -> None:", "    \"\"\"The merge path's insert branch writes a fresh rollup row with both scores NULL.", "", "    Covers the other half of the upsert: when the matched event has no row yet for the", "    incoming document's model, the row is created rather than conflict-updated. The", "    create path in ``synthesis_service`` is tested separately, so without this the", "    insert branch here carries no coverage.", "    \"\"\"", "    _stub_embeddings(monkeypatch)", "    _stub_merge_llm(monkeypatch, _success_outcome())", "", "    from accelerate_models.ai.app.models.ai_models import AiModel", "    from accelerate_models.ai.app.models.doc_ai_model_map import DocAiModelMap", "    from accelerate_models.event_synthesis.app.models.source_event_ai_models import (", "        SourceEventAiModel,", "    )", "", "    ai_model_id = uuid4()", "    source_event_id = merge_link_fixtures[\"source_event_id\"]", "", "    async with sessionmanager_accelerate.session() as db:", "        db.add(AiModel(id=ai_model_id, name=f\"merge-insert-{ai_model_id}\", description=\"test\"))", "        await db.flush()", "        db.add(", "            DocAiModelMap(", "                document_id=merge_link_fixtures[\"doc_id\"],", "                ai_model_id=ai_model_id,", "                is_match=True,", "                meta={\"data_model_response_id\": str(uuid4())},", "            )", "        )", "        await db.commit()", "", "    try:", "        # No pre-existing rollup row for this model, so the upsert takes the insert branch.", "        async with sessionmanager_accelerate.session() as db:", "            existing = (", "                await db.execute(", "                    select(SourceEventAiModel).where(", "                        SourceEventAiModel.source_event_id == source_event_id,", "                        SourceEventAiModel.ai_model_id == ai_model_id,", "                    )", "                )", "            ).all()", "        assert existing == []", "", "        raw_event = await _load_raw_event(merge_link_fixtures[\"raw_event_id\"])", "        await _make_service().merge_link_one(", "            raw_event,", "            matched_source_event_id=source_event_id,", "            correlation_id=None,", "        )", "", "        async with sessionmanager_accelerate.session() as db:", "            rollup = (", "                await db.execute(", "                    select(SourceEventAiModel).where(", "                        SourceEventAiModel.source_event_id == source_event_id,", "                        SourceEventAiModel.ai_model_id == ai_model_id,", "                    )", "                )", "            ).scalar_one()", "", "        assert rollup.matched_document_count == 1", "        assert rollup.weighted_match_score is None", "        assert rollup.max_confidence is None", "    finally:", "        async with sessionmanager_accelerate.session() as db:", "            await db.execute(", "                text(", "                    \"DELETE FROM event_synth.source_event_ai_models \"", "                    \"WHERE source_event_id = :se_id AND ai_model_id = :ai_id\"", "                ),", "                {\"se_id\": str(source_event_id), \"ai_id\": str(ai_model_id)},", "            )", "            await db.execute(", "                text(", "                    \"DELETE FROM ai.doc_ai_model_map \"", "                    \"WHERE document_id = :doc_id AND ai_model_id = :ai_id\"", "                ),", "                {\"doc_id\": merge_link_fixtures[\"doc_id\"], \"ai_id\": str(ai_model_id)},", "            )", "            await db.execute(", "                text(\"DELETE FROM ai.ai_models WHERE id = :id\"), {\"id\": str(ai_model_id)}", "            )", "            await db.commit()"], "blocks": [{"start": 1, "end": 67, "label": "Imports and module setup"}, {"start": 68, "end": 114, "label": "def _category_and_type"}, {"start": 115, "end": 272, "label": "def merge_link_fixtures"}, {"start": 273, "end": 283, "label": "def _stub_embeddings"}, {"start": 284, "end": 292, "label": "def _stub_merge_llm"}, {"start": 293, "end": 314, "label": "def _success_outcome"}, {"start": 315, "end": 323, "label": "def _outage_outcome"}, {"start": 324, "end": 357, "label": "def _make_service"}, {"start": 358, "end": 365, "label": "def _load_raw_event"}, {"start": 366, "end": 417, "label": "def test_confirmed_merge_updates_source_event_and_writes_article_linked_change"}, {"start": 418, "end": 454, "label": "def test_ac2_narrative_merge_safely_on_llm_success"}, {"start": 455, "end": 510, "label": "def test_ac2_degenerate_merge_response_preserves_existing_key_details_and_hints"}, {"start": 511, "end": 555, "label": "def test_conservative_link_when_merge_llm_unavailable_preserves_narrative_fields"}, {"start": 556, "end": 586, "label": "def test_merge_recomputes_retrieval_text_and_embedding_after_material_change"}, {"start": 587, "end": 650, "label": "def test_ac3_retrieval_embedding_failure_preserves_prior_value"}, {"start": 651, "end": 682, "label": "def test_ac4_platform_document_evidence_stores_doc_id_and_raw_event_id"}, {"start": 683, "end": 703, "label": "def test_risk_4_null_doc_article_map_raises_data_error"}, {"start": 704, "end": 721, "label": "def test_risk_8_matched_source_event_missing_raises_data_error"}, {"start": 722, "end": 772, "label": "def test_duplicate_document_link_skips_count_confidence_scoring_retrieval_change_write"}, {"start": 773, "end": 830, "label": "def test_ac6_entity_role_precedence_and_geo_increment"}, {"start": 831, "end": 895, "label": "def test_ac6_incoming_multi_role_same_entity_picks_highest_precedence"}, {"start": 896, "end": 915, "label": "def _spy_logger_warnings"}, {"start": 916, "end": 996, "label": "def test_risk_2_dedup_decision_drift_on_replay"}, {"start": 997, "end": 1040, "label": "def test_risk_7_event_status_lifecycle_regression"}, {"start": 1041, "end": 1075, "label": "def test_idempotent_replay_returns_duplicate_evidence"}, {"start": 1076, "end": 1188, "label": "def test_merge_preserves_existing_taxonomy_when_incoming_differs"}, {"start": 1189, "end": 1221, "label": "def test_merge_writes_event_confidence_from_llm_output"}, {"start": 1222, "end": 1254, "label": "def test_merge_keeps_existing_event_confidence_when_llm_abstains"}, {"start": 1255, "end": 1287, "label": "def test_merge_takes_max_event_confidence_on_outage_when_incoming_stronger"}, {"start": 1288, "end": 1329, "label": "def test_merge_never_lowers_event_confidence_on_outage"}, {"start": 1330, "end": 1344, "label": "def test_protocol_conformance"}, {"start": 1345, "end": 1353, "label": "def test_ac7_no_merged_into_id_column_on_source_events"}, {"start": 1354, "end": 1372, "label": "def _load_article_linked_change"}, {"start": 1373, "end": 1411, "label": "def _seed_existing_entities"}, {"start": 1412, "end": 1460, "label": "def test_new_entity_emits_entity_added_with_role"}, {"start": 1461, "end": 1486, "label": "def test_role_change_emits_entity_role_changed"}, {"start": 1487, "end": 1542, "label": "def test_entity_added_detected_beyond_top_n"}, {"start": 1543, "end": 1617, "label": "def test_non_top_n_role_change_emits_reason_without_recompute"}, {"start": 1618, "end": 1717, "label": "def test_merge_increments_count_and_preserves_legacy_score_on_rollup"}, {"start": 1718, "end": 1805, "label": "def test_merge_inserts_new_rollup_row_with_both_scores_null"}], "lineCount": 1805, "sha256": "91ebf1392b193bd2cc5b1c1e0231297a65313bf1102acda52a04a3c8c9e54a02", "endsWithNewline": true});
